pub struct OwnedActorFailureAcknowledged{instance:usize,source:semio_framework_job::OriginalSourceBinding,reference:semio_framework_actor::ActorFailureCallReference,address:usize,length:u32}
impl OwnedActorFailureAcknowledged{pub fn matches_header(&self,address:usize,length:usize)->bool{self.address==address&&self.length as usize==length}pub fn reference(&self)->semio_framework_actor::ActorFailureCallReference{self.reference}pub fn proves(&self,state:&OwnedGuestInstance,cx:&StepContext<'_>)->bool{self.instance==state as*const OwnedGuestInstance as usize&&self.source.matches(cx)}}
