impl OwnedGuestInstance{
 pub fn original_call_requires_execution(&self)->bool{self.original_call.as_ref().is_some_and(|owner|owner.phase==Phase::Driving)&&!self.original_core.as_ref().is_some_and(|core|core.original_host_call_pending())&&!self.original_host.as_ref().is_some_and(|host|host.reply_pending())}
 pub fn original_call_is_pending(&self)->bool{self.original_call.is_some()}
}
