pub(super) fn validate(state:&OwnedGuestInstance,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{state.original_source.as_ref().ok_or_else(||refused("original guest call requires its retained genuine source"))?.validate_context(cx)?;let epoch=cx.original_source_epoch().ok_or_else(||refused("original guest call requires its actual issued epoch"))?;let input=state.original_startup_input.ok_or_else(||refused("original guest call requires its actual final startup input"))?;if epoch<input.epoch||state.original_call.as_ref().is_some_and(|owner|epoch<owner.input.epoch){return Err(refused("original guest call precedes its actual initiating input").into())}state.original_core.as_ref().ok_or_else(||refused("original guest call has no actual paid Core"))?.validate_original_context(state.artifact.original_actor_module(),cx)}
