mod original_retirement_export_law{use super::*;#[test]fn only_confirmed_cleanup_exports_can_enter_original_retirement(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/retirement-exports.json")).unwrap();for export in OwnedSemioExport::ALL.iter(){let name=format!("{export:?}");let expected=fixture["cleanup"].as_array().unwrap().iter().any(|value|value.as_str()==Some(name.as_str()));assert_eq!(original_retirement_export(*export),expected,"{name}");}}}
